Singleton - Java Code Example (Thread-Safe)
// Thread-safe Singleton with double-checked locking
public
class
ThreadSafeSingleton
{
// volatile ensures visibility across threads
private
static
volatile
ThreadSafeSingleton instance;
private
String data;
private
ThreadSafeSingleton
(String data)
{
this
.data = data;
// Simulate slow initialization
try
{
Thread.sleep(
1000
);
}
catch
(InterruptedException e) {
e.printStackTrace();
}
// Double-checked locking
public
static
ThreadSafeSingleton
getInstance
(String data)
{
ThreadSafeSingleton
result
=
instance;
if
(result!=
null
) {
return
result;
// Fast path: no locking needed
}
synchronized
(ThreadSafeSingleton.class) {
if
(instance ==
null
) {
instance =
new
ThreadSafeSingleton
(data);
}
return
instance;
}
public
String
getData
()
{
return
data; }
}
